test('windows-xpc-integration: valid synthetic fixed-case observation', () => {
  const m = memfs();
  const record = makeRecord('valid');
  const entry = fixedXpcJournalObservation({
    serializedRecord: JSON.stringify(record),
    projectId: 'project-a',
    candidateId: 'candidate-a',
    receiptId: 'receipt-a',
    createdAt: 100,
    ttlMs: 1000
  }).entry;
  assert.strictEqual(entry.id, '0123456789abcdef0123456789abcdef:0:fixed-xpc');
  assert.strictEqual(entry.stage, 'fixed-xpc');
  assert.strictEqual(entry.state, 'SUCCEEDED');
  assert.strictEqual(entry.payload.caseName, 'valid');
  assert.deepStrictEqual(entry.payload.reasons, []);
  assert.strictEqual(entry.payload.clientOutcome, 'REPLY_RECEIVED');
  assert.strictEqual(entry.payload.meaning, 'FIXED_CASE_OBSERVATION_ONLY');
  const {owner} = openJournalOwner({
    path: '/j/current-xpc.jsonl',
    fs: m.fs,
    config: {projectId: 'project-a', maxEntries: 8, heartbeatTtlMs: 10, redactPaths: []},
    now: 100
  });
  const {status, entry: recordedEntry} = recordJournalObservation({owner, entry, now: 100});
  assert.strictEqual(status, 'RECORDED');
  assert.strictEqual(recordedEntry.id, entry.id);
  const {snapshot} = inspectJournalOwner({owner});
  assert.strictEqual(snapshot.state, 'OPEN');
  assert.strictEqual(snapshot.meaning, 'HISTORY_OBSERVATIONS_ONLY');
  assert.strictEqual(snapshot.entries[0].entry.id, entry.id);
  assert.strictEqual(snapshot.entries[0].historical, true);
  const reopen = openJournalOwner({
    path: '/j/current-xpc.jsonl',
    fs: m.fs,
    config: {projectId: 'project-a', maxEntries: 8, heartbeatTtlMs: 10, redactPaths: []},
    now: 100
  });
  assert.strictEqual(reopen.snapshot.entries[0].entry.id, entry.id);
  const flags = ['authorizing','generatedCodeExecuted','isolationAccepted','nativeProductAccepted','serviceIdentityAttested','serviceTerminationProven','sourceManifestVerified'];
  for (const flag of flags) {
    assert.strictEqual(entry.payload[flag], false);
    assert.strictEqual(reopen.snapshot.entries[0].entry.payload[flag], false);
  }
});

